// Description: Ranox/Lanox port -- engine-gap wiring 2/5. Binds
//              TRIGGER_LINE_ACTION_TYPE.TAT_LINE_CHANGE_TYPE (=7,
//              KTDXLIB/KTDGLineMap.h) to reassigning
//              CKTDGLineMap::LineData::lineType at runtime, the same
